import { createRootRoute, createRoute, createRouter, lazyRouteComponent } from '@octanejs/tanstack-router';
import { Shell } from './Shell.tsrx';
import { Home } from './Home.tsrx';

const rootRoute = createRootRoute({ component: Shell });
const homeRoute = createRoute({ getParentRoute: () => rootRoute, path: '/', component: Home });
const threadRoute = createRoute({
	getParentRoute: () => rootRoute,
	path: 'c/$threadId',
	component: lazyRouteComponent(() => import('../conversation/Thread.tsrx'), 'Thread'),
});
const settingsRoute = createRoute({
	getParentRoute: () => rootRoute,
	path: 'settings',
	component: lazyRouteComponent(() => import('../settings/Settings.tsrx'), 'Settings'),
});

export const routeTree = rootRoute.addChildren([homeRoute, threadRoute, settingsRoute]);

export function makeRouter(options: { history: any; basepath: string }) {
	return createRouter({ routeTree, history: options.history, basepath: options.basepath, defaultPreload: false });
}
