// Keeps keyboard focus inside an overlay while it is open and gives it back
// to the opener on close.
const FOCUSABLE = 'button:not([disabled]), [href], input:not([disabled]), select, textarea, [tabindex]:not([tabindex="-1"])';

export function trapFocus(container: HTMLElement) {
	const opener = container.ownerDocument.activeElement as HTMLElement | null;
	const focusables = () => Array.from(container.querySelectorAll<HTMLElement>(FOCUSABLE)).filter((el) => el.getClientRects().length > 0);
	const onKeyDown = (event: KeyboardEvent) => {
		if (event.key !== 'Tab')
			return;
		const items = focusables();
		if (!items.length)
			return;
		const first = items[0];
		const last = items[items.length - 1];
		const active = container.ownerDocument.activeElement;
		if (event.shiftKey && active === first) {
			event.preventDefault();
			last.focus();
		} else if (!event.shiftKey && active === last) {
			event.preventDefault();
			first.focus();
		}
	};
	container.addEventListener('keydown', onKeyDown);
	focusables()[0]?.focus({ preventScroll: true });
	return () => {
		container.removeEventListener('keydown', onKeyDown);
		opener?.focus?.({ preventScroll: true });
	};
}
