// Batched product telemetry: page-view, business and performance events are
// built as objects, serialized and handed to sendBeacon in batches, like the
// reference's first-party event pipeline. The page runtime makes the beacon a
// sink.
import { env } from '../app/env.ts';

type Event = { type: string; name: string; time: number; seq: number; props: Record<string, unknown>; context: Record<string, unknown> };

const BATCH_SIZE = 8;

export class Telemetry {
	#queue: Event[] = [];
	#seq = 0;
	#context: Record<string, unknown>;
	#flushScheduled = false;
	sent = 0;

	constructor(context: Record<string, unknown>) {
		this.#context = context;
	}

	#push(type: string, name: string, props: Record<string, unknown>) {
		this.#queue.push({ type, name, time: env.now + this.#seq, seq: this.#seq++, props, context: { ...this.#context, route: env.route() } });
		if (this.#queue.length >= BATCH_SIZE)
			this.flush();
		else if (!this.#flushScheduled) {
			this.#flushScheduled = true;
			env.afterTask(() => this.flush());
		}
	}

	business(name: string, props: Record<string, unknown> = {}) {
		this.#push('business', name, props);
	}

	performance(name: string, props: Record<string, unknown> = {}) {
		this.#push('performance', name, props);
	}

	pageView(path: string) {
		this.#push('page-view', 'page_view', { path, referrer: '', title: 'Lumen' });
	}

	exposure(event: object) {
		this.#push('exposure', 'gate_exposure', event as Record<string, unknown>);
	}

	flush() {
		this.#flushScheduled = false;
		if (!this.#queue.length)
			return;
		const batch = this.#queue;
		this.#queue = [];
		const body = JSON.stringify({ batch, sentAt: env.now + this.#seq, version: '2.14.0' });
		this.sent += batch.length;
		navigator.sendBeacon('api/telemetry', body);
	}
}
