// Web vitals (attribution build), reported as performance events.
import { onCLS, onFCP, onINP, onLCP, onTTFB } from 'web-vitals/attribution';

export function startVitals(telemetry: any) {
	const report = (metric: any) => telemetry.performance('web_vital', { name: metric.name, value: metric.value, rating: metric.rating, id: metric.id, target: metric.attribution?.interactionTarget ?? metric.attribution?.element ?? null });
	onCLS(report);
	onFCP(report);
	onINP(report, { reportAllChanges: true });
	onLCP(report);
	onTTFB(report);
}
