// Access to the page runtime (src/runtime/page-runtime.js), with fallbacks
// for the server render.
const runtime = typeof window !== 'undefined' ? (window as any).__chat : null;

export const env = {
	now: runtime?.now ?? Date.UTC(2026, 10, 2, 9, 30, 0),
	benchmark: runtime?.benchmark ?? false,
	track<T>(promise: Promise<T>): Promise<T> {
		return runtime ? runtime.track(promise) : promise;
	},
	signal(name: string, detail?: unknown) {
		runtime?.signal(name, detail);
	},
	afterTask(callback: () => void) {
		if (runtime)
			runtime.afterTask(callback);
		else
			setTimeout(callback, 0);
	},
	onFlush(callback: () => void) {
		if (runtime)
			runtime.onFlush(callback);
	},
	route(): string {
		return typeof location !== 'undefined' ? location.pathname : '/';
	},
};
