// The page's bootstrap state: the inline JSON the server render embeds
// (#app-state), read once by the client entry.
import { STRINGS } from './strings.ts';

export type Boot = {
	locale: string;
	strings: typeof STRINGS;
	theme: 'light' | 'dark';
	accent: string;
	sidebarOpen: boolean;
	viewportWidth: number;
	region: string;
	settings: Record<string, any>;
	gates: any;
	ads: any[];
	home: any;
	frame: any;
};

let boot: Boot | null = null;

export function setBoot(value: Boot) {
	boot = value;
}

export function getBoot(): Boot {
	return boot!;
}

export function getAds() {
	return boot!.ads;
}
