// A feature-gate client in the style of the hosted gate services: it is
// bootstrapped from inline JSON, evaluates gates, dynamic configs and layers
// from that payload and logs an exposure the first time each one is read.
export type GatePayload = {
	gates: Record<string, { value: boolean; rule: string; secondary?: string[] }>;
	configs: Record<string, { value: Record<string, unknown>; rule: string; group?: string }>;
	layers: Record<string, { value: Record<string, unknown>; rule: string; allocated?: string; explicit?: string[] }>;
	hash: string;
	time: number;
};

export class GateClient {
	#payload: GatePayload;
	#exposures = new Map<string, number>();
	#log: (event: object) => void;
	#overrides = new Map<string, boolean>();

	constructor(payload: GatePayload, log: (event: object) => void) {
		this.#payload = payload;
		this.#log = log;
	}

	#expose(kind: string, name: string, rule: string, extra?: object) {
		const key = `${kind}:${name}`;
		const count = this.#exposures.get(key) ?? 0;
		this.#exposures.set(key, count + 1);
		if (count === 0)
			this.#log({ eventName: `gates::${kind}_exposure`, metadata: { name, rule, hash: this.#payload.hash, time: this.#payload.time, ...extra } });
	}

	checkGate(name: string): boolean {
		const override = this.#overrides.get(name);
		if (override !== undefined)
			return override;
		const gate = this.#payload.gates[name];
		this.#expose('gate', name, gate?.rule ?? 'default', { value: gate?.value ?? false, secondary: gate?.secondary ?? [] });
		return gate?.value ?? false;
	}

	getConfig(name: string) {
		const config = this.#payload.configs[name];
		this.#expose('config', name, config?.rule ?? 'default', { group: config?.group });
		const value = config?.value ?? {};
		return { get: <T,>(key: string, fallback: T): T => (key in value ? (value[key] as T) : fallback) };
	}

	getLayer(name: string) {
		const layer = this.#payload.layers[name];
		const value = layer?.value ?? {};
		return {
			get: <T,>(key: string, fallback: T): T => {
				if (!(key in value))
					return fallback;
				this.#expose('layer', `${name}.${key}`, layer.rule, { allocated: layer.allocated, explicit: layer.explicit?.includes(key) ?? false });
				return value[key] as T;
			},
		};
	}

	override(name: string, value: boolean) {
		this.#overrides.set(name, value);
	}
}
